import json

with open("/home/USER/runs/paper/qwen-hpl0-u1-turns/frozen/held-out/play/users/u060/system/state/workspace/programs/task-cf3b6090.json", "r") as f:
    demos = json.load(f)

def load_boundary(data):
    for r in range(len(data['input'])):
        if all(x == 2 for x in data['input'][r]):
            return r
    return None

star_deltas = [(-1,-2), (-1,2), (0,-1), (0,1), (1,0)]

def run_simple_5star(demo):
    inp = [list(row) for row in demo['input']]
    boundary = load_boundary(demo)
    rows, cols = len(inp), len(inp[0])

    # Find input 4s BEFORE removing
    input_4s = [(r, c) for r in range(boundary) for c in range(cols) if inp[r][c] == 4]

    for r in range(boundary):
        for c in range(cols):
            if inp[r][c] == 4:
                inp[r][c] = 0

    for r, c in input_4s:
        for dr, dc in star_deltas:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                inp[nr][nc] = 4

    return inp

def compare(demo):
    result = run_simple_5star(demo)
    result_4s = set((r, c) for r in range(len(result)) for c in range(len(result[0])) if result[r][c] == 4)
    expected_4s = set((r, c) for r in range(len(demo['output'])) for c in range(len(demo['output'][0])) if demo['output'][r][c] == 4)

    extra = result_4s - expected_4s
    missing = expected_4s - result_4s

    print(f"Demo: {len(result_4s)} generated, {len(expected_4s)} expected")
    print(f"  Extra: {extra}, Missing: {missing}")
    return result_4s == expected_4s

print("5-star comparison:")
for i, demo in enumerate(demos):
